import React from 'react';
import styled from 'styled-components';
import ActivityCard from './ActivityCard';
import Header from './Header';
import {
  FaPlus,
  FaMinus,
  FaTimes,
  FaBrain,
  FaBook,
  FaPalette,
  FaDivide,
  FaCalculator,
  FaGlobe,
  FaPuzzlePiece,
  FaProjectDiagram,
  FaKeyboard
} from 'react-icons/fa';

const LandingContainer = styled.div`
  min-height: 100vh;
  padding-bottom: 3rem;
`;

const ActivitiesSection = styled.section`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
`;

const SectionTitle = styled.h2`
  text-align: center;
  font-size: 2.5rem;
  background: linear-gradient(45deg, var(--brand-teal), var(--brand-orange));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 3rem;
  font-weight: 700;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  
  @media (max-width: 768px) {
    font-size: 2rem;
  }
`;

const CardsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  margin-bottom: 3rem;
  
  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
`;

const Footer = styled.footer`
  text-align: center;
  padding: 2rem;
  color: white;
  opacity: 0.8;
`;

const FooterLogo = styled.img`
  height: 22px;
  width: auto;
  vertical-align: -4px;
  margin-left: 0.4rem;
  filter: drop-shadow(0 6px 10px rgba(0, 0, 0, 0.25));
`;

const ManifestoDetails = styled.details`
  margin: 1rem auto 0;
  max-width: 760px;
  text-align: left;
  font-size: 0.95rem;
  line-height: 1.5;
  opacity: 0.9;

  summary {
    cursor: pointer;
    list-style: none;
    outline: none;
  }

  summary::-webkit-details-marker {
    display: none;
  }
`;

const ManifestoSummary = styled.summary`
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
`;

const ManifestoContent = styled.div`
  margin-top: 0.75rem;
  opacity: 0.95;

  p {
    margin: 0.5rem 0;
  }

  a {
    color: inherit;
    text-decoration: underline;
    text-underline-offset: 3px;
  }
`;

const Landing = ({ onNavigate }) => {
  const donationUrl = process.env.REACT_APP_DONATION_URL;

  const activities = [
    {
      id: 1,
      icon: <FaPlus />,
      title: "Práctica de Sumas",
      description: "Aprende y practica operaciones de suma de manera divertida con ejercicios interactivos.",
      color: "#4CAF50"
    },
    {
      id: 2,
      icon: <FaMinus />,
      title: "Práctica de Restas",
      description: "Domina las restas con ejercicios progresivos y entretenidos juegos matemáticos.",
      color: "#FF5722"
    },
    {
      id: 3,
      icon: <FaTimes />,
      title: "Tablas de Multiplicar",
      description: "Memoriza las tablas de multiplicar jugando y practicando de forma interactiva.",
      color: "#9C27B0"
    },
    {
      id: 4,
      icon: <FaDivide />,
      title: "División Divertida",
      description: "Aprende división paso a paso con explicaciones claras y ejercicios prácticos.",
      color: "#FF9800"
    },
    {
      id: 5,
      icon: <FaBrain />,
      title: "Conocimientos Generales",
      description: "Expande tu cultura general con preguntas sobre ciencia, historia y geografía.",
      color: "#2196F3"
    },
    {
      id: 6,
      icon: <FaBook />,
      title: "Vocabulario",
      description: "Enriquece tu vocabulario aprendiendo nuevas palabras y sus significados.",
      color: "#795548"
    },
    {
      id: 7,
      icon: <FaPalette />,
      title: "Colores y Formas",
      description: "Reconoce colores, formas geométricas y desarrolla habilidades visuales.",
      color: "#E91E63"
    },
    {
      id: 12,
      icon: <FaProjectDiagram />,
      title: "Geometría",
      description: "Área y perímetro: triángulos, rectángulos, paralelogramos y circunferencias con retos y bonus.",
      color: "#845EF7"
    },
    {
      id: 8,
      icon: <FaCalculator />,
      title: "Matemáticas Mixtas",
      description: "Combina todas las operaciones matemáticas en desafíos emocionantes.",
      color: "#607D8B"
    },
    {
      id: 9,
      icon: <FaGlobe />,
      title: "Inglés",
      description: "Aprende inglés formando frases y vocabulario con el Dragón Tragón.",
      color: "#E67E22"
    },
    {
      id: 10,
      icon: <FaBrain />,
      title: "Avanzado",
      description: "Retos de lógica y matemáticas para subir de nivel con puzzles más difíciles.",
      color: "#16A085"
    },
    {
      id: 11,
      icon: <FaPuzzlePiece />,
      title: "Puzzles",
      description: "Puzzles cooperativos tipo Fireboy & Watergirl con niveles procedurales por semilla.",
      color: "#2D9CDB"
    },
    {
      id: 13,
      icon: <FaKeyboard />,
      title: "Mecanografía",
      description: "Aprende a escribir correctamente en la Typer Dungeon. Derrota monstruos escribiendo palabras.",
      color: "#8B4513"
    }
  ];

  const handleActivityClick = (activity) => {
    alert(`¡Próximamente disponible: ${activity.title}!`);
  };

  const onSelectActivity = (activityId) => {
    const categories = {
      1: 'addition',
      2: 'subtraction',
      3: 'multiplication',
      4: 'division',
      5: 'knowledge',
      6: 'vocabulary',
      7: 'shapes',
      12: 'geometria',
      8: 'mixed_math',
      9: 'english',
      10: 'advanced',
      11: 'puzzles'
    };

    // Games that open directly without going through game-selector
    const directGames = {
      13: 'typerdungeon',
    };

    if (directGames[activityId]) {
      onNavigate(directGames[activityId]);
    } else if (categories[activityId]) {
      // Multiplicación pasa primero por la pantalla de selección de tablas/cifras
      if (categories[activityId] === 'multiplication') {
        onNavigate('multiplication-config', 'multiplication');
      } else {
        onNavigate('game-selector', categories[activityId]);
      }
    } else {
      const activity = activities.find(act => act.id === activityId);
      handleActivityClick(activity || { title: "esta actividad" });
    }
  };


  return (
    <LandingContainer>
      <Header />
      <ActivitiesSection>
        <SectionTitle>🎯 Elige tu Actividad</SectionTitle>
        {/* Original CardsGrid for basic math and general knowledge */}
        <CardsGrid>
          {activities.slice(0, 6).map(activity => ( // Display first 6 activities in the original grid
            <ActivityCard
              key={activity.id}
              icon={activity.icon}
              title={activity.title}
              description={activity.description}
              color={activity.color}
              onClick={() => onSelectActivity(activity.id)}
            />
          ))}
        </CardsGrid>
      </ActivitiesSection>

      <ActivitiesSection>
        <CardsGrid>
          {activities.slice(6).map(activity => (
            <ActivityCard
              key={activity.id}
              icon={activity.icon}
              title={activity.title}
              description={activity.description}
              color={activity.color}
              onClick={() => onSelectActivity(activity.id)}
            />
          ))}
        </CardsGrid>
      </ActivitiesSection>
      <Footer>
        <p>
          © 2024 Edutika - Aprendiendo mientras nos divertimos
          <FooterLogo src={`${process.env.PUBLIC_URL}/edutikalogo.png`} alt="Edutika" />
        </p>
        <ManifestoDetails>
          <ManifestoSummary>Sobre el proyecto</ManifestoSummary>
          <ManifestoContent>
            <p>
              Edutika es un proyecto educativo sin publicidad y gratuito para cualquiera.
            </p>
            <p>
              Si te resulta útil y quieres ayudar con el mantenimiento (por ejemplo, dominio/servidor),
              {donationUrl ? (
                <>
                  puedes aportar una donación de forma discreta{' '}
                  <a href={donationUrl} target="_blank" rel="noreferrer">
                    aquí
                  </a>
                  .
                </>
              ) : (
                <>puedes aportar una donación de forma discreta.</>
              )}
            </p>
          </ManifestoContent>
        </ManifestoDetails>
      </Footer>
    </LandingContainer>
  );
};

export default Landing;
